<?php
/**  * Manager Validation Metrics API  * Returns transaction module metrics for Manager Dashboard  */
header('Content-Type: application/json');
if (session_status() === PHP_SESSION_NONE) session_start();  require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';
require_login();  $me = current_user();
$role = role_key($me['role'] ?? '');
$station_id = (int)user_station_id();  // Only manager/admin roles can access
if (!in_array($role, ['manager', 'admin', 'superadmin'])) {  echo json_encode(['success' => false, 'error' => 'Access denied']);  exit;
}  if (!$station_id) {  echo json_encode(['success' => false, 'error' => 'Station not assigned']);  exit;
}  try {  // Transactions are official on staff save; no manager approval queue remains.  $pending_txn_query = $pdo->prepare("  SELECT COUNT(*) AS pending_transactions  FROM (  SELECT id FROM merchandise_transactions  WHERE station_id = ?  AND 1 = 0  UNION ALL  SELECT id FROM job_orders  WHERE station_id = ?  AND 1 = 0  ) AS combined  ");  $pending_txn_query->execute([$station_id, $station_id]);  $pending_transactions = (int)$pending_txn_query->fetchColumn();  // ── Processed Today (official/corrected records) ──  $validated_today_query = $pdo->prepare("  SELECT COUNT(*) AS validated_today  FROM (  SELECT id FROM merchandise_transactions  WHERE station_id = ?  AND LOWER(validation_status) IN ('official', 'completed', 'approved', 'validated', 'adjusted')  AND DATE(COALESCE(transaction_date, created_at)) = CURDATE()  UNION ALL  SELECT id FROM job_orders  WHERE station_id = ?  AND LOWER(validation_status) IN ('official', 'completed', 'approved', 'validated', 'adjusted')  AND DATE(created_at) = CURDATE()  ) AS combined  ");  $validated_today_query->execute([$station_id, $station_id]);  $validated_today = (int)$validated_today_query->fetchColumn();  // ── Variance Alerts (flagged anomalies) ──  // Check for fuel variance, inventory discrepancies, unusual pricing  $variance_alerts = 0;  // Fuel variance (today)  $fuel_variance_query = $pdo->prepare("  SELECT COUNT(*) FROM (  SELECT fuel_type  FROM fuel_transactions  WHERE station_id = ?  AND DATE(COALESCE(transaction_date, created_at)) = CURDATE()  GROUP BY fuel_type  HAVING ABS(SUM((present_reading - previous_reading) - liters_sold)) > 2  ) AS variances  ");  $fuel_variance_query->execute([$station_id]);  $variance_alerts += (int)$fuel_variance_query->fetchColumn();  // Inventory discrepancies (from variance_reports table if exists)  try {  $inv_variance_query = $pdo->prepare("  SELECT COUNT(*) FROM variance_reports  WHERE station_id = ?  AND resolved = 0  AND DATE(created_at) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)  ");  $inv_variance_query->execute([$station_id]);  $variance_alerts += (int)$inv_variance_query->fetchColumn();  } catch (Exception $e) {  // Table might not exist  }  // ── Validation Flow Chart (Pending vs Validated) ──  // Weekly stats for trend  $validation_flow_query = $pdo->prepare("  SELECT  DATE(COALESCE(validated_at, created_at)) AS date,  SUM(0) AS pending,  SUM(CASE WHEN LOWER(validation_status) IN ('official', 'completed', 'approved', 'validated', 'adjusted') THEN 1 ELSE 0 END) AS validated  FROM (  SELECT validation_status, validated_at, created_at  FROM merchandise_transactions  WHERE station_id = ?  AND DATE(created_at) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)  UNION ALL  SELECT validation_status, validated_at, created_at  FROM job_orders  WHERE station_id = ?  AND DATE(created_at) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)  ) AS combined  GROUP BY DATE(COALESCE(validated_at, created_at))  ORDER BY date ASC  ");  $validation_flow_query->execute([$station_id, $station_id]);  $validation_flow = $validation_flow_query->fetchAll(PDO::FETCH_ASSOC);  // Transform for chart  $validation_chart = [  'labels' => [],  'pending' => [],  'validated' => []  ];  foreach ($validation_flow as $row) {  $validation_chart['labels'][] = date('M d', strtotime($row['date']));  $validation_chart['pending'][] = (int)$row['pending'];  $validation_chart['validated'][] = (int)$row['validated'];  }  // ── Variance Trend Chart (last 7 days) ──  $variance_trend_query = $pdo->prepare("  SELECT  DATE(COALESCE(transaction_date, created_at)) AS date,  COUNT(*) AS variance_count  FROM (  SELECT fuel_type, transaction_date, created_at  FROM fuel_transactions  WHERE station_id = ?  AND DATE(COALESCE(transaction_date, created_at)) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)  GROUP BY fuel_type, DATE(COALESCE(transaction_date, created_at))  HAVING ABS(SUM((present_reading - previous_reading) - liters_sold)) > 2  ) AS variances  GROUP BY date  ORDER BY date ASC  ");  $variance_trend_query->execute([$station_id]);  $variance_trend = $variance_trend_query->fetchAll(PDO::FETCH_ASSOC);  // Transform for chart  $variance_chart = [  'labels' => [],  'counts' => []  ];  foreach ($variance_trend as $row) {  $variance_chart['labels'][] = date('M d', strtotime($row['date']));  $variance_chart['counts'][] = (int)$row['variance_count'];  }  echo json_encode([  'success' => true,  'data' => [  'pending_transactions' => $pending_transactions,  'validated_today' => $validated_today,  'variance_alerts' => $variance_alerts,  'validation_flow' => $validation_chart,  'variance_trend' => $variance_chart  ],  'timestamp' => date('Y-m-d H:i:s')  ]);  } catch (Exception $e) {  echo json_encode([  'success' => false,  'error' => 'Failed to fetch metrics: ' . $e->getMessage()  ]);
}
